solution:
function ProductExceptSelf(nums: int[]) -> int[] {
  let n = nums.length();
  let res: int[] = [];
  let i = 0;
  while (i < n) {
    res.push(1);
    i += 1;
  }
  let prefix = 1;
  let j = 0;
  while (j < n) {
    res[j] = prefix;
    prefix = prefix * nums[j];
    j += 1;
  }
  let suffix = 1;
  let k = n - 1;
  while (k >= 0) {
    res[k] = res[k] * suffix;
    suffix = suffix * nums[k];
    k -= 1;
  }
  return res;
}
